import {escortBlocked,escortBlockReason} from './escort.js';
import {expeditionHold,expeditionBlockerCount,expeditionGuardCount,expeditionTarget,CITY_EXPEDITION,EXPEDITION_STEPS,getExpedition} from './expedition.js';
import {project} from './projection.js?v=0.29.0';
export function drawExpeditionTarget(c,game,labels=false){const t=expeditionTarget(game);if(!t)return;const q=project(t.x,t.y,2),near=Math.hypot(game.player.x-t.x,game.player.y-t.y)<=t.radius,blocked=t.kind==='escort'&&escortBlocked(game,t),progress=expeditionHold(game,t)/t.duration,rx=['defend','escort','relay'].includes(t.kind)?t.radius*Math.sqrt(1.5):32,ry=['defend','escort','relay'].includes(t.kind)?t.radius/Math.sqrt(2):18;c.save();try{if(labels){if(t.kind==='breach')for(const b of t.blockers||[]){const o=game.world.obstacles.find(o=>o.x===b.x&&o.y===b.y&&!o.destroyed);if(o){const mark=project(o.x+o.w/2,o.y+o.h/2,38);c.fillStyle='#ffcf80';c.font='700 11px system-ui';c.textAlign='center';c.fillText('▼ 차단 차량',mark.x,mark.y);}}c.font='700 11px system-ui';c.textAlign='center';c.fillStyle='#142b30';c.fillRect(q.x-79,q.y-110,158,37);c.strokeStyle='#b6a37a';c.lineWidth=1;c.strokeRect(q.x-79,q.y-110,158,37);c.fillStyle='#f0dbab';c.fillText(t.title,q.x,q.y-95);c.font='10px system-ui';c.fillText(t.kind==='relay'?'채널 '+(t.channel===0?'A':'B')+' · 범위 안에서 송신':t.kind==='escort'?(blocked?escortBlockReason(game,t)==='player'?'차량 앞을 비우세요':'견인로 정리 필요':'차량 곁에서 이동 · 감염자 제거'):t.kind==='breach'?'F 수동 사격 · 차단 차량 파괴':t.kind==='clear'?'정예 제거 후 통로 접근':t.kind==='defend'?'범위 안에서 전송 방어':near?'X 길게 누르기':'임무 지점',q.x,q.y-81);return;}c.strokeStyle=blocked?'#e58665':near?'#ffe5a3':'#c3aa73';c.fillStyle=t.kind==='defend'?'rgba(125,195,183,.055)':'rgba(202,172,105,.12)';c.lineWidth=2;c.beginPath();c.ellipse(q.x,q.y,rx,ry,0,0,Math.PI*2);c.fill();c.stroke();c.strokeStyle='#ffdc89';c.lineWidth=4;c.beginPath();c.ellipse(q.x,q.y,32,18,0,-Math.PI/2,-Math.PI/2+Math.PI*2*progress);c.stroke();}finally{c.restore();}}
export function createExpeditionUI(){const link=document.createElement('link');link.rel='stylesheet';link.href=new URL('./expedition-ui.css',import.meta.url).href;document.head.append(link);const button=document.createElement('button');button.id='expedition-action';button.className='expedition-action';button.hidden=true;button.type='button';button.innerHTML='<strong></strong><span></span><i aria-hidden="true"></i>';document.body.append(button);let held=false;
const release=()=>{held=false;};button.onpointerdown=e=>{if(button.disabled)return;e.preventDefault();held=true;button.setPointerCapture?.(e.pointerId);};for(const type of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(type,release);button.onkeydown=e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();e.stopPropagation();held=true;}};button.onkeyup=e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();e.stopPropagation();release();}};button.onblur=release;
return {get pressed(){return held;},release,update(game,covered=false){const t=expeditionTarget(game),visible=!!t&&game.state==='playing'&&!covered,changed=button.hidden===visible;button.hidden=!visible;if(!visible){release();return changed;}const near=Math.hypot(game.player.x-t.x,game.player.y-t.y)<=t.radius;button.disabled=!near||['defend','clear','escort','relay','breach'].includes(t.kind);if(!near||['defend','clear','escort','relay','breach'].includes(t.kind))release();button.querySelector('strong').textContent=t.action;button.querySelector('span').textContent=t.kind==='relay'?(near?'채널 '+(t.channel===0?'A':'B')+' 송신 중':'채널 '+(t.channel===0?'A':'B')+' 중계기로 이동'):t.kind==='escort'?(near?(escortBlocked(game,t)?escortBlockReason(game,t)==='player'?'차량 앞을 비우세요':'견인로 정리 필요':'견인 중 · '+Math.floor(expeditionHold(game,t)/t.duration*100)+'%'):'차량 곁으로 복귀하세요'):t.kind==='breach'?(expeditionBlockerCount(game,t)>0?'F 수동 사격 · 차단 차량 '+expeditionBlockerCount(game,t)+'대':'견인로 확보 중'):t.kind==='clear'?(expeditionGuardCount(game)>0?'통로 정예 '+expeditionGuardCount(game)+'마리':'금색 기록함 표식에 접근하세요'):t.kind==='defend'?(near?(t.preparation?'냉각 정화 · 남은 ':t.action+' · 남은 ')+Math.ceil(t.duration-expeditionHold(game,t))+'초':'금색 전송 범위로 이동하세요'):near?'X / 버튼을 길게 누르세요':'금색 표식에 접근하세요';button.querySelector('i').style.transform=`scaleX(${expeditionHold(game,t)/t.duration})`;return changed;}};
}
export function expeditionResultHTML(game){const definition=getExpedition(game?.result?.expeditionId);if(!definition||definition.vaccineEnding&&game.result.vaccineRecovered!==true||!game.result.won||game.result.objectivesCompleted!==definition.steps.length)return '';return '<section class="story-dossier" aria-label="원정 회수 기록"><p class="eyebrow">LAST SIGNAL / '+definition.title+'</p><p>'+definition.steps.at(-1).clue+'</p><p>'+(definition.debrief?definition.debrief:definition.id===CITY_EXPEDITION.id?'무전 채널과 억제제, 병원 이송 기록을 회수했습니다. 옥상 원정이 열렸습니다.':'옥상 두 동과 연결교를 통과해 중계 신호를 전송했습니다. 병원 방향 구조 경로를 추적합니다.')+'</p><p class="muted">'+(definition.vaccineEnding&&game.result.vaccineRecovered===true?'첫 백신 원액을 확보했습니다. 생존자에게 돌아갈 냉각 운송 경로를 확보했습니다.':'백신은 아직 확보하지 못했습니다.')+'</p></section>';}
